const form=document.querySelector('#enquiry-draft');form.addEventListener('submit',async e=>{e.preventDefault();const data=new FormData(form),draft=`Apparition enquiry: ${data.get('topic')}\nGuitar / reference: ${data.get('reference')}\n\n${data.get('question')}`;try{await navigator.clipboard.writeText(draft);document.querySelector('#enquiry-status').textContent='Draft copied. No message has been sent.';}catch{const box=document.querySelector('#draft-fallback');box.hidden=false;box.value=draft;box.focus();box.select();document.querySelector('#enquiry-status').textContent='Select and copy your draft. No message has been sent.';}});
